using Anarchy.Toolkit.Core.Exceptions;
using Serilog;
using Serilog.Configuration;

namespace Anarchy.Toolkit.Infrastructure.Observability.Serilog.Extension.Observability;

/// <summary>
/// Indicates the retention period for the logs generated by the application.
/// </summary>
public enum RetentionPeriod
{
    ThreeDays = 3,
    SevenDays = 7,
    FifteenDays = 15,
    ThirtyDays = 30,
    NinetyDays = 90,
}

/// <summary>
/// Enrichers for the ownership and housekeeping properties log pipelines commonly route on (team, app group,
/// cost center, retention). Every property name can be overridden to follow an organisation's own convention.
/// </summary>
public static class StandardPropertiesEnricherExtensions
{
    public const string DefaultRetentionPropertyName = "retention";
    public const string DefaultTeamPropertyName = "team";
    public const string DefaultAppGroupPropertyName = "appgroup";
    public const string DefaultCostCenterPropertyName = "CostCenter";

    /// <param name="cfg">The logger enrichment configuration</param>
    extension(LoggerEnrichmentConfiguration cfg)
    {
        /// <summary>
        /// Enriches all log events with the retention period, in days.
        /// </summary>
        /// <exception cref="UndefinedEnumValueException">Thrown when <paramref name="retentionPeriod"/> is invalid.</exception>
        public LoggerConfiguration WithLogRetention(RetentionPeriod retentionPeriod,
                                                    string propertyName = DefaultRetentionPropertyName)
        {
            return !Enum.IsDefined(retentionPeriod) ?
                throw new UndefinedEnumValueException(nameof(retentionPeriod), retentionPeriod) :
                cfg.WithProperty(propertyName, (int)retentionPeriod);
        }

        /// <summary>
        /// Enriches all log events with the owning team.
        /// </summary>
        /// <exception cref="ArgumentException">Thrown when <paramref name="team"/> is invalid.</exception>
        public LoggerConfiguration WithTeam(string team, string propertyName = DefaultTeamPropertyName)
        {
            return string.IsNullOrWhiteSpace(team) ?
                throw new EmptyArgumentException(nameof(team), "Team cannot be null or whitespace.") :
                cfg.WithProperty(propertyName, team);
        }

        /// <summary>
        /// Enriches all log events with the application group the application belongs to.
        /// </summary>
        /// <exception cref="ArgumentException">Thrown when <paramref name="appGroup"/> is invalid.</exception>
        public LoggerConfiguration WithAppGroup(string appGroup, string propertyName = DefaultAppGroupPropertyName)
        {
            return string.IsNullOrWhiteSpace(appGroup) ?
                throw new EmptyArgumentException(nameof(appGroup), "App Group name cannot be null or whitespace.") :
                cfg.WithProperty(propertyName, appGroup);
        }

        /// <summary>
        /// Enriches all log events with the cost center paying for the application.
        /// </summary>
        /// <exception cref="ArgumentException">Thrown when <paramref name="costCenter"/> is invalid.</exception>
        public LoggerConfiguration WithCostCenter(string costCenter,
                                                  string propertyName = DefaultCostCenterPropertyName)
        {
            return string.IsNullOrWhiteSpace(costCenter) ?
                throw new EmptyArgumentException(nameof(costCenter), "Cost center cannot be null or whitespace.") :
                cfg.WithProperty(propertyName, costCenter);
        }

        /// <summary>
        /// Enriches all log events with the cost center read from the given environment variable, for hosting
        /// platforms that expose it to every instance.
        /// </summary>
        /// <exception cref="MissingEnvironmentVariableException">Thrown when the variable is not set.</exception>
        public LoggerConfiguration WithCostCenterFromEnvironment(string environmentVariableName,
                                                                 string propertyName = DefaultCostCenterPropertyName)
        {
            if (string.IsNullOrWhiteSpace(environmentVariableName))
                throw new EmptyArgumentException(nameof(environmentVariableName),
                    "Environment variable name cannot be null or whitespace.");

            var costCenter = Environment.GetEnvironmentVariable(environmentVariableName, EnvironmentVariableTarget.Process);

            return string.IsNullOrEmpty(costCenter) ?
                throw new MissingEnvironmentVariableException(environmentVariableName) :
                cfg.WithProperty(propertyName, costCenter);
        }
    }
}
